%[text] %[text:anchor:H_CD51BFF9] ### Four-noded bilinear Reissner-Mindlin elements with Assumed Natural Strain (ANS)
%[text] %[text:anchor:H_239AFEE9] #### Solution of the linear equation system
uQ1ANS = zeros(numDOFsQ1, 1);
uQ1ANS(freeDOFsQ1, 1) = ...
    K_Q1_ANS(freeDOFsQ1, freeDOFsQ1)\F_Q1_ANS(freeDOFsQ1);
%[text] %[text:anchor:H_A488E2D5] #### Visualization of the solution in terms of the vertical displacement field
mshCurrQ1ANS = mshQ1;
scaling = 1; %[control:slider:5676]{"position":[11,12]}
mshCurrQ1ANS.nodes(:, 3) = mshCurrQ1ANS.nodes(:, 3) + ...
    scaling*uQ1ANS(1:3:end, 1);
numVertices = numel(mshQ1.nodes(:, 1));
figure, %[output:98d19f85]
plotMesh2d(mshCurrQ1ANS, numVertices, false); %[output:98d19f85]
hold on; %[output:98d19f85]
scalVer = 1;
[xsQ1ANS, ysQ1ANS, zsQ1ANS] = ...
    createSupports3D(mshCurrQ1ANS.nodes, homDOFsQ1, scalVer);
for k = 1:length(xsQ1(:, 1))
    plot3(xsQ1ANS(k, :), ysQ1ANS(k, :), zsQ1ANS(k, :), 'Linewidth', 2, ... %[output:98d19f85]
        'Color', 'black'); %[output:98d19f85]
end
hold off; %[output:98d19f85]
axis equal; %[output:98d19f85]
xlabel("$x$", "Interpreter","latex") %[output:98d19f85]
ylabel("$y$", "Interpreter","latex") %[output:98d19f85]
zlabel("$z$", "Interpreter","latex") %[output:98d19f85]
title("Plate's deformation using Q1 (ANS) elements") %[output:98d19f85]
%[text] %[text:anchor:H_81F289A7] #### Visualization of the solution in terms of the rotational field
mshCurrQ1ANSBetay = mshQ1;
scaling = 1; %[control:slider:9ceb]{"position":[11,12]}
mshCurrQ1ANSBetay.nodes(:, 3) = mshCurrQ1ANSBetay.nodes(:, 3) + ...
    scaling*uQ1ANS(2:3:end, 1);
numVertices = numel(mshQ1.nodes(:, 1));
figure, %[output:11aa513a]
plotMesh2d(mshCurrQ1ANSBetay, numVertices, false); %[output:11aa513a]
hold on; %[output:11aa513a]
scalVer = 1;
[xsQ1ANS, ysQ1ANS, zsQ1ANS] = ... 
    createSupports3D(mshCurrQ1ANSBetay.nodes, homDOFsQ1, scalVer);
for k = 1:length(xsQ1(:, 1))
    plot3(xsQ1ANS(k, :), ysQ1ANS(k, :), zsQ1ANS(k, :), 'Linewidth', 2, ... %[output:11aa513a]
        'Color', 'black'); %[output:11aa513a]
end
hold off; %[output:11aa513a]
axis equal; %[output:11aa513a]
xlabel("$x$", "Interpreter","latex") %[output:11aa513a]
ylabel("$y$", "Interpreter","latex") %[output:11aa513a]
zlabel("$z$", "Interpreter","latex") %[output:11aa513a]
title("Distribution of rotation field $\beta_x$ using Q1 (ANS) elements", ... %[output:group:4d020446] %[output:11aa513a]
    Interpreter="latex") %[output:group:4d020446] %[output:11aa513a]
